func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_storage.py): %v", name, err)
	}
	return raw
}

// om builds an OrderedMap literal for tests: om("k", v, "k2", v2, ...).
func om(kv ...any) *OrderedMap {
	if len(kv)%2 != 0 {
		panic("om: odd key/value count")
	}
	m := NewOrderedMap()
	for i := 0; i < len(kv); i += 2 {
		m.Set(kv[i].(string), kv[i+1])
	}
	return m
}

// getOM fetches a nested *OrderedMap or fails the test.
func getOM(t *testing.T, m *OrderedMap, key string) *OrderedMap {
	t.Helper()
	v, ok := m.Get(key)
	if !ok {
		t.Fatalf("key %q missing", key)
	}
	nested, ok := v.(*OrderedMap)
	if !ok {
		t.Fatalf("key %q is %T; want *OrderedMap", key, v)
	}
	return nested
}

// jsonUnmarshalFile reads a testdata golden and decodes it.
func jsonUnmarshalFile(t *testing.T, name string, v any) error {
	t.Helper()
	return json.Unmarshal(goldenBytes(t, name), v)
}

func repeatByte(ch byte, n int) []byte {
	b := make([]byte, n)
	for i := range b {
		b[i] = ch
	}
	return b
}

func mustWrite(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o666); err != nil {
		t.Fatal(err)
	}
}

