// Port of test_atomic_write_text.
func TestAtomicWriteText(t *testing.T) {
	tmp := t.TempDir()
	path := filepath.Join(tmp, "note.md")
	if err := AtomicWriteText(path, "hello"); err != nil {
		t.Fatalf("atomic_write_text: %v", err)
	}
	got, _ := os.ReadFile(path)
	if string(got) != "hello" {
		t.Fatalf("content = %q; want %q", got, "hello")
	}
	// Overwrite is atomic and clean
	if err := AtomicWriteText(path, strings.Repeat("second version", 100)); err != nil {
		t.Fatalf("overwrite: %v", err)
	}
	got, _ = os.ReadFile(path)
	if string(got) != strings.Repeat("second version", 100) {
		t.Fatal("overwrite content mismatch")
	}
	// No temp files left behind
	leftovers := []string{}
	entries, _ := os.ReadDir(tmp)
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), ".tmp_") {
			leftovers = append(leftovers, e.Name())
		}
	}
	if len(leftovers) != 0 {
		t.Fatalf("temp leftovers: %v", leftovers)
	}
}

// Port of test_atomic_write_bytes.
func TestAtomicWriteBytes(t *testing.T) {
	tmp := t.TempDir()
	path := filepath.Join(tmp, "banner.png")
	data := append([]byte("\x89PNG\r\n\x1a\n"), repeatByte('x', 2000)...)
	if err := AtomicWriteBytes(path, data); err != nil {
		t.Fatalf("atomic_write_bytes: %v", err)
	}
	got, err := os.ReadFile(path)
	if err != nil || len(got) < 4 || string(got[:4]) != "\x89PNG" {
		t.Fatalf("banner bytes wrong: %d bytes, %v", len(got), err)
	}
}

// Port of test_safe_filename_defeats_traversal.
func TestSafeFilenameDefeatsTraversal(t *testing.T) {
	// No path separators and no '..' can survive — traversal impossible.
	out := SafeFilename("../../etc/passwd")
	if strings.Contains(out, "/") || strings.Contains(out, "\\") || strings.Contains(out, "..") {
		t.Fatalf("traversal survived: %q", out)
	}
	if strings.Contains(SafeFilename(`a/b\c..d`), "..") {
		t.Fatal("traversal survived in a/b\\c..d")
	}
	if got := SafeFilename("my.repo-name_2"); got != "my_repo-name_2" {
		t.Fatalf("safe_filename(my.repo-name_2) = %q; want my_repo-name_2", got)
	}
	// (dots -> underscore matches the ORIGINAL main.py filename behavior
	//  that existing notes / undo lists were built on)
}

// Port of test_unique_path.
func TestUniquePath(t *testing.T) {
	tmp := t.TempDir()
	path := filepath.Join(tmp, "note.md")
	mustWrite(t, path, "first")
	second := UniquePath(path)
	if !strings.HasSuffix(second, "_v1.md") {
		t.Fatalf("unique_path = %q; want _v1.md suffix", second)
	}
	mustWrite(t, second, "second")
	third := UniquePath(path)
	if !strings.HasSuffix(third, "_v2.md") {
		t.Fatalf("unique_path = %q; want _v2.md suffix", third)
	}
}

