// Port of test_merge_config_preserves_unknown_keys — THE regression test
// for the save_config key-wipe: cloudflare_* and gdrive_* keys MUST
// survive a save.
func TestMergeConfigPreservesUnknownKeys(t *testing.T) {
	existing := om(
		"ollama", om("base_url", "http://localhost:11434", "model", "old", "custom_key", "keep-me"),
		"timeout_per_repo", 120,
		"max_retries", 7,
		"delay_between_api_calls", 2.5,
		"cloudflare_install_id", "uuid-123",
		"cloudflare_shared_secret", "abc",
		"gdrive_folder_id", "xyz",
		"user_added_key", 42,
	)
	updates := om(
		"ollama", om("model", "new-model"),
		"proxy", om("host", "127.0.0.1"),
	)
	merged := MergeConfig(existing, updates)

	check := func(key string, want any) {
		t.Helper()
		got, ok := merged.Get(key)
		if !ok || !reflect.DeepEqual(got, want) {
			t.Errorf("merged[%q] = %v (ok=%v); want %v", key, got, ok, want)
		}
	}
	check("timeout_per_repo", 120) // NOT stomped
	check("max_retries", 7)        // NOT stomped
	check("delay_between_api_calls", 2.5)
	check("cloudflare_install_id", "uuid-123") // preserved
	check("cloudflare_shared_secret", "abc")   // preserved
	check("gdrive_folder_id", "xyz")           // preserved
	check("user_added_key", 42)                // preserved
	ollama := getOM(t, merged, "ollama")
	if v, _ := ollama.Get("model"); v != "new-model" {
		t.Errorf("ollama.model = %v; want new-model (updated)", v)
	}
	if v, _ := ollama.Get("base_url"); v != "http://localhost:11434" {
		t.Errorf("ollama.base_url = %v; want kept", v)
	}
	if v, _ := ollama.Get("custom_key"); v != "keep-me" {
		t.Errorf("ollama.custom_key = %v; want keep-me (nested keep)", v)
	}
	proxy := getOM(t, merged, "proxy")
	if v, _ := proxy.Get("host"); v != "127.0.0.1" {
		t.Errorf("proxy.host = %v; want 127.0.0.1", v)
	}
}

