// ---------------------------------------------------------------------------
// Port of test_phase0.py test_storage_atomic_writes_are_gated (the gate is
// the atomic writers' — dryrun just records).
// ---------------------------------------------------------------------------

func TestAtomicWritesAreGatedByDryRun(t *testing.T) {
	dryrun.Disable()
	dryrun.Clear()
	defer func() { dryrun.Disable(); dryrun.Clear() }()

	tmp := t.TempDir()
	dryrun.Enable()
	p1 := filepath.Join(tmp, "vault", "note.md")
	if err := AtomicWriteText(p1, "note body"); err != nil {
		t.Fatalf("gated atomic_write_text must not error: %v", err)
	}
	if err := AtomicWriteBytes(filepath.Join(tmp, "b.png"), []byte("\x89PNG")); err != nil {
		t.Fatalf("gated atomic_write_bytes must not error: %v", err)
	}
	if err := WriteConfigFile(filepath.Join(tmp, "config.json"), om("a", 1)); err != nil {
		t.Fatalf("gated write_config_file must not error: %v", err)
	}
	// nothing written at all
	names, _ := os.ReadDir(tmp)
	if len(names) != 0 {
		t.Fatalf("disk was touched while dry-run enabled: %v", names)
	}
	if got := dryrun.EntryCount(); got != 3 {
		t.Fatalf("entry_count = %d; want 3", got)
	}
	// config writes are recorded too — a dry-run must not advance
	// last_processed_msg_id / model choices in the real config.
	sawConfig := false
	for _, e := range dryrun.Entries() {
		if strings.HasSuffix(e.Path, "config.json") {
			sawConfig = true
		}
	}
	if !sawConfig {
		t.Error("config.json write was not recorded")
	}
	// and no temp leftovers from the gated atomic writers
	dryrun.Disable()
	if err := AtomicWriteText(p1, "note body"); err != nil {
		t.Fatalf("real write after disable: %v", err)
	}
	got, _ := os.ReadFile(p1)
	if string(got) != "note body" {
		t.Fatalf("after disable content = %q", got)
	}
}

// ---------------------------------------------------------------------------
// Atomicity probes (spec-core-storage §Tests: a failed write must leave
// the pre-existing content intact; readers never see partial content).
// ---------------------------------------------------------------------------

// A failed rename (target replaced by a directory mid-flight) must return
// an error, clean up its temp file, and change nothing about the target.
func TestFailedWriteKeepsExistingContent(t *testing.T) {
	tmp := t.TempDir()
	path := filepath.Join(tmp, "note.md")
	if err := AtomicWriteText(path, "PRE-EXISTING"); err != nil {
		t.Fatal(err)
	}
	// Make the target a non-empty directory: os.Rename(file → dir) fails.
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(path, "child"), 0o777); err != nil {
		t.Fatal(err)
	}
	if err := AtomicWriteText(path, "NEW"); err == nil {
		t.Fatal("rename onto a non-empty dir must fail")
	}
	// no temp leftovers
	entries, _ := os.ReadDir(tmp)
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), ".tmp_") {
			t.Fatalf("temp leftover after failed write: %s", e.Name())
		}
	}
	// nothing truncated, nothing partial: the target path is untouched.
	if _, err := os.Stat(filepath.Join(path, "child")); err != nil {
		t.Fatalf("target was modified by the failed write: %v", err)
	}
}

// Torn-write probe: while a writer rewrites the same file, a concurrent
// reader must only ever observe complete old or complete new content.
func TestReadersNeverSeePartialContent(t *testing.T) {
	tmp := t.TempDir()
	path := filepath.Join(tmp, "note.md")
	old := strings.Repeat("OLD", 1000)
	if err := AtomicWriteText(path, old); err != nil {
		t.Fatal(err)
	}
	stop := make(chan struct{})
	readErr := make(chan string, 1)
	go func() {
		for {
			select {
			case <-stop:
				return
			default:
			}
			data, err := os.ReadFile(path)
			if err != nil {
				readErr <- err.Error()
				return
			}
			s := string(data)
			if s != old && !strings.HasPrefix(s, "NEW-") {
				readErr <- "torn read: " + s[:40]
				return
			}
		}
	}()
	for i := 0; i < 50; i++ {
		if err := AtomicWriteText(path, "NEW-"+strings.Repeat("x", 3000)+"-"+strconv.Itoa(i)); err != nil {
			t.Fatal(err)
		}
	}
	close(stop)
	select {
	case msg := <-readErr:
		t.Fatal(msg)
	default:
	}
}

