// THE T-12 ACCEPTANCE: the config round-trip is byte-stable against
// Python's write_config_file on a real config copy (the reference repo's
// committed app/config.example.json — placeholders only).
func TestGoldenConfigRoundTrip(t *testing.T) {
	cfg, err := DecodeJSON(goldenBytes(t, "config_roundtrip.input.json"))
	if err != nil {
		t.Fatalf("decode input: %v", err)
	}
	tmp := filepath.Join(t.TempDir(), "config.json")
	if err := WriteConfigFile(tmp, cfg); err != nil {
		t.Fatalf("write_config_file: %v", err)
	}
	got, err := os.ReadFile(tmp)
	if err != nil {
		t.Fatal(err)
	}
	want := goldenBytes(t, "config_roundtrip.golden.json")
	if string(got) != string(want) {
		t.Fatalf("config round-trip drifted from Python's bytes.\n--- want (python) --\n%s\n--- got (go) --\n%s",
			want, got)
	}
}

// merge_config golden: ORDER (Python dict insertion semantics), nested
// merges, the tuning-key law, and the setdefault append order.
func TestGoldenMergeConfig(t *testing.T) {
	existing, err := DecodeJSON(goldenBytes(t, "merge_existing.input.json"))
	if err != nil {
		t.Fatalf("decode existing: %v", err)
	}
	updates, err := DecodeJSON(goldenBytes(t, "merge_updates.input.json"))
	if err != nil {
		t.Fatalf("decode updates: %v", err)
	}
	writeAndCompare := func(merged *OrderedMap, golden string) {
		t.Helper()
		tmp := filepath.Join(t.TempDir(), "merged.json")
		if err := WriteConfigFile(tmp, merged); err != nil {
			t.Fatal(err)
		}
		got, _ := os.ReadFile(tmp)
		want := goldenBytes(t, golden)
		if string(got) != string(want) {
			t.Fatalf("%s drifted.\n--- want (python) --\n%s\n--- got (go) --\n%s", golden, want, got)
		}
	}
	writeAndCompare(MergeConfig(existing, updates), "merge_result.golden.json")
	writeAndCompare(MergeConfig(NewOrderedMap(), updates), "merge_defaults.golden.json")
}

// storage corpus golden: safe_filename traversal corpus,
// build_note_filename probes, unique_path over a deterministic tree, the
// os.path.splitext name grammar, and the float-repr law.
func TestGoldenStorageCorpus(t *testing.T) {
	var golden struct {
		Schema            int        `json:"schema"`
		SafeFilename      [][]string `json:"safe_filename"`
		BuildNoteFilename [][]any    `json:"build_note_filename"`
		UniquePath        [][]string `json:"unique_path"`
		Splitext          [][]any    `json:"splitext"`   // [name, [root, ext]]
		FloatRepr         [][]any    `json:"float_repr"` // [json-number, repr-string]
	}
	if err := jsonUnmarshalFile(t, "storage_corpus.golden.json", &golden); err != nil {
		t.Fatalf("parse golden: %v", err)
	}

	for _, pair := range golden.SafeFilename {
		if got := SafeFilename(pair[0]); got != pair[1] {
			t.Errorf("safe_filename(%q) = %q; golden %q", pair[0], got, pair[1])
		}
	}

	for _, probe := range golden.BuildNoteFilename {
		repo, _ := probe[0].(string)
		cat, _ := probe[1].(string)
		tagsAny, _ := probe[2].([]any)
		tags := make([]string, len(tagsAny))
		for i, tg := range tagsAny {
			tags[i], _ = tg.(string)
		}
		want, _ := probe[3].(string)
		if got := BuildNoteFilename(repo, cat, tags); got != want {
			t.Errorf("build_note_filename(%q,%q,%q) = %q; golden %q", repo, cat, tags, got, want)
		}
	}

	// unique_path over the same deterministic tree the generator built
	tmp := t.TempDir()
	mustWrite(t, filepath.Join(tmp, "note.md"), "first")
	u1 := UniquePath(filepath.Join(tmp, "note.md"))
	mustWrite(t, u1, "second")
	u2 := UniquePath(filepath.Join(tmp, "note.md"))
	mustWrite(t, filepath.Join(tmp, "file"), "x")
	u3 := UniquePath(filepath.Join(tmp, "file"))
	mustWrite(t, filepath.Join(tmp, ".hidden"), "x")
	u4 := UniquePath(filepath.Join(tmp, ".hidden"))
	u5 := UniquePath(filepath.Join(tmp, "fresh.md"))
	for i, got := range []string{u1, u2, u3, u4, u5} {
		wantIn, wantOut := golden.UniquePath[i][0], golden.UniquePath[i][1]
		if filepath.Base(got) != wantOut {
			t.Errorf("unique_path[%d] = %q; golden %q (input %q)", i, got, wantOut, wantIn)
		}
	}

	// splitext grammar (the tmp-suffix + unique_path base/ext rule)
	for _, probe := range golden.Splitext {
		name, _ := probe[0].(string)
		pair, _ := probe[1].([]any)
		root, _ := pair[0].(string)
		ext, _ := pair[1].(string)
		gotBase, gotExt := pySplitExt(name)
		if gotBase != root || gotExt != ext {
			t.Errorf("pySplitExt(%q) = (%q, %q); golden (%q, %q)", name, gotBase, gotExt, root, ext)
		}
	}

	// float repr: the input types are re-declared here (int vs float is a
	// Python-side distinction the JSON golden cannot carry); the golden
	// contributes the expected strings.
	floats := []any{0.5, 2.0, 1e15, 1e16, 1e-05, 1.2345678901234568e17, 0.0001,
		3.141592653589793, 1234.5, 1e100, -2.5, 60, 3}
	if len(floats) != len(golden.FloatRepr) {
		t.Fatalf("float table len %d != golden %d", len(floats), len(golden.FloatRepr))
	}
	for i, v := range floats {
		want, _ := golden.FloatRepr[i][1].(string)
		if got := PyDumps(v); got != want {
			t.Errorf("PyDumps(%v) = %q; golden %q", v, got, want)
		}
	}
}
